/*
 * TASK B boot harness: drives the REAL lv2 SPU syscall path end-to-end on a
 * real SPU ELF (image_open -> group_create -> thread_initialize -> group_start
 * -> group_join), then verifies a sentinel landed in the thread's local store.
 *
 * SPU program (one PT_LOAD, vaddr 0, entry 0):
 *   00 il   r4,0x200   ; store target
 *   04 il   r3,42      ; r3 = 42 (splat to all words)
 *   08 stqd r3,0(r4)   ; LS[0x200] quadword = r3 ; preferred word bytes 0..3 = 00 00 00 2A
 *   0C stop
 * After group_join, read LS[0x200] via spu_thread_get_local_store(tid); expect 42.
 *
 * Build: compile lv2_register.c with -DSPU_BOOT_SELFTEST and link the real
 * spu_elf / spu_interp / spu_channels / spu_fallback objects. vm_base is a real
 * buffer here; sys_fs_translate_path (identity), sys_event_queue_push_by_id
 * (no-op), and the 10 sys_*_init symbols (referenced only by the never-called
 * lv2_register_all_syscalls) are stubbed so the object links.
 */
#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <stdlib.h>

#include "lv2_syscall_table.h"        /* ppu_context, lv2_syscall_table (via -I runtime/syscalls) */
#include "ps3emu/spu_fallback.h"      /* spu_thread_get_local_store (via -I include) */

/* ---- handlers exposed by the SPU_BOOT_SELFTEST shim in lv2_register.c ---- */
int64_t boot_selftest_spu_image_open(ppu_context*);
int64_t boot_selftest_spu_thread_group_create(ppu_context*);
int64_t boot_selftest_spu_thread_initialize(ppu_context*);
int64_t boot_selftest_spu_thread_group_start(ppu_context*);
int64_t boot_selftest_spu_thread_group_join(ppu_context*);

/* ---- minimal guest address space ---- */
#define VM_SIZE (1u << 20)
static uint8_t g_vm[VM_SIZE];
uint8_t* vm_base = g_vm;              /* satisfies `extern uint8_t* vm_base` */

/* ---- stub the deps the linker demands but the test path doesn't exercise ---- */
void sys_fs_translate_path(const char* ps3_path, char* host_path, int host_path_size) {
    if (host_path && host_path_size > 0) {
        strncpy(host_path, ps3_path, (size_t)host_path_size - 1);
        host_path[host_path_size - 1] = 0;
    }
}
int sys_event_queue_push_by_id(uint32_t q, uint64_t s, uint64_t d1, uint64_t d2, uint64_t d3) {
    (void)q;(void)s;(void)d1;(void)d2;(void)d3; return 0;   /* never reached (no queue connected) */
}
/* lv2_register_all_syscalls (never called by this test) references these. */
void sys_ppu_thread_init (lv2_syscall_table* t){(void)t;}
void sys_mutex_init      (lv2_syscall_table* t){(void)t;}
void sys_cond_init       (lv2_syscall_table* t){(void)t;}
void sys_semaphore_init  (lv2_syscall_table* t){(void)t;}
void sys_rwlock_init     (lv2_syscall_table* t){(void)t;}
void sys_timer_init      (lv2_syscall_table* t){(void)t;}
void sys_event_init      (lv2_syscall_table* t){(void)t;}
void sys_memory_init     (lv2_syscall_table* t){(void)t;}
void sys_vm_init         (lv2_syscall_table* t){(void)t;}
void sys_fs_init         (lv2_syscall_table* t){(void)t;}

/* ---- SPU ELF builders (mirror test_spu_integration_main.c) ---- */
#define EM_SPU 23
#define PT_LOAD 1
#define EHDR 52u
#define PHDR 32u
static void be16(uint8_t*p,uint16_t v){p[0]=(uint8_t)(v>>8);p[1]=(uint8_t)v;}
static void be32(uint8_t*p,uint32_t v){p[0]=(uint8_t)(v>>24);p[1]=(uint8_t)(v>>16);p[2]=(uint8_t)(v>>8);p[3]=(uint8_t)v;}
static uint32_t e_ri16(uint32_t op9,uint32_t i16,uint32_t rt){return ((op9&0x1FF)<<23)|((i16&0xFFFF)<<7)|(rt&0x7F);}
static uint32_t e_ri10(uint32_t op8,int i10,uint32_t ra,uint32_t rt){return ((op8&0xFF)<<24)|(((uint32_t)i10&0x3FF)<<14)|((ra&0x7F)<<7)|(rt&0x7F);}
static uint32_t e_rr(uint32_t op11,uint32_t rb,uint32_t ra,uint32_t rt){return ((op11&0x7FF)<<21)|((rb&0x7F)<<14)|((ra&0x7F)<<7)|(rt&0x7F);}

static void gw_be32(uint32_t ea, uint32_t v){ be32(g_vm + ea, v); }
static uint32_t gr_be32(uint32_t ea){ const uint8_t*p=g_vm+ea; return ((uint32_t)p[0]<<24)|((uint32_t)p[1]<<16)|((uint32_t)p[2]<<8)|p[3]; }

int main(void) {
