    uint32_t prog[] = {
        e_ri16(0x081, 0x200, 4),   /* il   r4,0x200 */
        e_ri16(0x081, 0x2A,  3),   /* il   r3,42    */
        e_ri10(0x24,  0, 4,  3),   /* stqd r3,0(r4) */
        e_rr  (0x000, 0, 0,  0),   /* stop          */
