    elf[0]=0x7F;elf[1]='E';elf[2]='L';elf[3]='F';elf[4]=1;elf[5]=2;elf[6]=1;
    be16(elf+16,2); be16(elf+18,EM_SPU); be32(elf+24,0); be32(elf+28,EHDR);
    be16(elf+40,(uint16_t)EHDR); be16(elf+42,(uint16_t)PHDR); be16(elf+44,1);
    uint8_t* ph = elf+EHDR;
    be32(ph+0,PT_LOAD); be32(ph+4,code_off); be32(ph+8,0); be32(ph+12,0);
    be32(ph+16,code_sz); be32(ph+20,code_sz); be32(ph+24,5); be32(ph+28,16);
    for (uint32_t i=0;i<code_sz/4;i++) be32(elf+code_off+i*4, prog[i]);
    uint32_t elf_len = code_off + code_sz;

    const char* host_path = "test_spu_boot_image.elf";
    FILE* f = fopen(host_path, "wb");
    if (!f) { printf("[FAIL] boot: cannot write temp ELF\n"); return 1; }
    fwrite(elf, 1, elf_len, f); fclose(f);

    /* --- 2. lay out guest structs in g_vm --- */
    uint32_t img_ea   = 0x1000;   /* sys_spu_image (16 bytes) */
    uint32_t path_ea  = 0x2000;
    uint32_t out_gid  = 0x3000;
    uint32_t out_tid  = 0x3004;
    uint32_t cause_ea = 0x3008;
    uint32_t stat_ea  = 0x300C;
    uint32_t name_ea  = 0x3100;
    strcpy((char*)(g_vm + path_ea), host_path);   /* translate_path is identity */
    strcpy((char*)(g_vm + name_ea), "boot_test");

    ppu_context ctx; ppu_context_init(&ctx);

    /* --- 3. sys_spu_image_open(img_ea, path_ea) --- */
    ctx.gpr[3]=img_ea; ctx.gpr[4]=path_ea;
    boot_selftest_spu_image_open(&ctx);
    if (ctx.gpr[3]!=0) { printf("[FAIL] image_open rc=%lld\n",(long long)ctx.gpr[3]); ok=0; }
    if (gr_be32(img_ea+0)!=1) { printf("[FAIL] image type != USER\n"); ok=0; }       /* :993 */
    if (gr_be32(img_ea+4)!=0) { printf("[FAIL] image entry != 0 (got 0x%X)\n", gr_be32(img_ea+4)); ok=0; }

    /* --- 4. sys_spu_thread_group_create(out_gid, num=1, name, attr=0) --- */
    ctx.gpr[3]=out_gid; ctx.gpr[4]=1; ctx.gpr[5]=name_ea; ctx.gpr[6]=0;
    boot_selftest_spu_thread_group_create(&ctx);
    uint32_t gid = gr_be32(out_gid);
    if (ctx.gpr[3]!=0 || gid==0) { printf("[FAIL] group_create rc=%lld gid=0x%X\n",(long long)ctx.gpr[3],gid); ok=0; }

    /* --- 5. sys_spu_thread_initialize(out_tid, gid, num=0, img_ea, attr=0, args=0) --- */
    ctx.gpr[3]=out_tid; ctx.gpr[4]=gid; ctx.gpr[5]=0; ctx.gpr[6]=img_ea; ctx.gpr[7]=0; ctx.gpr[8]=0;
    boot_selftest_spu_thread_initialize(&ctx);
    uint32_t tid = gr_be32(out_tid);
    if (ctx.gpr[3]!=0 || tid==0) { printf("[FAIL] thread_init rc=%lld tid=0x%X\n",(long long)ctx.gpr[3],tid); ok=0; }

    /* --- 6. sys_spu_thread_group_start(gid) --- */
    ctx.gpr[3]=gid;
    boot_selftest_spu_thread_group_start(&ctx);
    if (ctx.gpr[3]!=0) { printf("[FAIL] group_start rc=%lld\n",(long long)ctx.gpr[3]); ok=0; }

    /* --- 7. sys_spu_thread_group_join(gid, cause_ea, stat_ea) -- BLOCKS until done --- */
    ctx.gpr[3]=gid; ctx.gpr[4]=cause_ea; ctx.gpr[5]=stat_ea;
    boot_selftest_spu_thread_group_join(&ctx);
    if (ctx.gpr[3]!=0) { printf("[FAIL] group_join rc=%lld\n",(long long)ctx.gpr[3]); ok=0; }

