    uint8_t* ls = spu_thread_get_local_store(tid);
    if (!ls) { printf("[FAIL] no local store for tid 0x%X\n", tid); ok=0; }
    else {
        uint32_t v = ((uint32_t)ls[0x200]<<24)|((uint32_t)ls[0x201]<<16)|
                     ((uint32_t)ls[0x202]<<8)|ls[0x203];
        if (v != 42u) { printf("[FAIL] LS[0x200]=%u (expected 42)\n", v); ok=0; }
    }

    remove(host_path);
    printf(ok ? "[PASS] boot: image_open->create->init->start->join ran SPU image, LS[0x200]=42\n"
              : "[FAIL] boot harness\n");
    return ok ? 0 : 1;
}

